/**
 * Метод для расчета накопленных процентов по простой процентной ставке.
 *
 * @param principal   Основная сумма долга (тело кредита/депозита)
 * @param annualRate  Годовая процентная ставка (в виде десятичной дроби, например, 0.05 для 5%)
 * @param from        Дата начала периода начисления
 * @param to          Дата окончания периода начисления
 * @return            Накопленная сумма процентов, округленная до двух знаков после запятой
 */
public BigDecimal accruedInterest(BigDecimal principal, BigDecimal annualRate,
                                  LocalDate from, LocalDate to) {
    // Проверка входных данных:
    // Если основная сумма меньше или равна нулю, либо дата окончания не позже даты начала,
    // то проценты не начисляются, и метод возвращает ноль.
    if (principal.signum() <= 0 || !to.isAfter(from)) {
        return BigDecimal.ZERO;
    }

    // Инициализация переменной для накопления общей суммы процентов
    BigDecimal total = BigDecimal.ZERO;

    // Цикл по каждому дню в периоде от даты 'from' до даты 'to' (не включая 'to')
    // Для каждого дня рассчитывается ежедневная сумма процентов и добавляется к общей сумме
    for (LocalDate d = from; d.isBefore(to); d = d.plusDays(1)) {
        // Определение количества дней в году для текущей даты d
        // Учитывается високосный год (366 дней) или обычный год (365 дней)
        int daysInYear = d.isLeapYear() ? 366 : 365;

        // Расчет ежедневной суммы процентов по формуле:
        // (Основная сумма * Годовая ставка) / Количество дней в году
        // Используется точное деление с 10 знаками после запятой и округлением HALF_UP
        BigDecimal daily = principal.multiply(annualRate)
            .divide(BigDecimal.valueOf(daysInYear), 10, RoundingMode.HALF_UP);

        // Добавление ежедневной суммы процентов к общей накопленной сумме
        total = total.add(daily);
    }

    // Возврат итоговой суммы процентов, округленной до двух знаков после запятой
    // (стандартное представление денежных сумм)
    return total.setScale(2, RoundingMode.HALF_UP);
}
