    // Инициализируем переменные для накопления сумм по дебету и кредиту.
    // Используем decimal для точных финансовых вычислений, избегая ошибок округления.
    decimal debit = 0m, credit = 0m;

    // Проходим по каждой строке проводки (постингу) для проверки и суммирования.
    foreach (var p in postings)
    {
        // Проверяем, что сумма положительная.
        // В стандартной модели проводок сумма всегда положительна,
        // а направление (дебет/кредит) определяется полем Side.
        // Отрицательные или нулевые суммы недопустимы и могут указывать на ошибку данных.
        if (p.Amount <= 0m)
            throw new ArgumentException($"Non-positive amount on account {p.Account}");

        // В зависимости от стороны (дебет или кредит) добавляем сумму к соответствующему итогу.
        if (p.Side == Side.Debit) debit += p.Amount;
        else credit += p.Amount;
    }

    // Проверяем баланс проводки: сумма всех дебетовых строк должна быть равна
    // сумме всех кредитовых строк. Это ключевой принцип двойной бухгалтерии.
    // Если суммы не равны, проводка некорректна и не может быть проведена.
    if (debit != credit)
        throw new InvalidOperationException($"Unbalanced entry: debit {debit}, credit {credit}");

    // Проверяем, что все строки проводки используют одну и ту же валюту.
    // Смешивание валют в одной проводке недопустимо, так как это нарушает
    // принцип эквивалентности дебетовых и кредитовых сумм (разные валюты
    // не могут быть напрямую сложены или сравнены без конвертации).
    if (postings.Select(p => p.Currency).Distinct().Count() > 1)
        throw new InvalidOperationException("Mixed currencies in one entry");
}
