/**
 * Вычисляет итоговые суммы по списку строк инвойса с учетом ставки НДС.
 *
 * @param lines - Массив строк инвойса, содержащих цену в копейках и количество.
 * @param vatRate - Ставка НДС в виде десятичной дроби (например, 0.2 для 20%).
 * @returns Объект с итогами: сумма без НДС (net), сумма НДС (vat) и общая сумма (gross).
 * @throws {RangeError} Если ставка НДС выходит за допустимый диапазон [0, 1].
 */
export function invoiceTotals(lines: InvoiceLine[], vatRate: number) {
  // Проверяем, что ставка НДС находится в допустимом диапазоне от 0 до 1 (включительно).
  // Это защита от некорректных данных, которые могут привести к неверным расчетам.
  if (vatRate < 0 || vatRate > 1) throw new RangeError(`vatRate out of range: ${vatRate}`);

  // Инициализируем переменные для накопления итоговых сумм:
  // net — сумма без НДС, vat — сумма НДС.
  let net = 0;
  let vat = 0;

  // Проходим по каждой строке инвойса.
  for (const line of lines) {
    // Пропускаем строки с некорректным количеством (меньше или равно нулю),
    // так как они не должны влиять на итоговые суммы.
    if (line.qty <= 0) continue;

    // Рассчитываем сумму строки без НДС:
    // умножаем цену в копейках на количество и округляем до целого числа копеек.
    const lineNet = Math.round(line.priceKop * line.qty);

    // Рассчитываем сумму НДС для данной строки:
    // умножаем сумму строки без НДС на ставку НДС и округляем до целого числа копеек.
    const lineVat = Math.round(lineNet * vatRate);

    // Добавляем рассчитанные значения к общим итоговым суммам.
    net += lineNet;
    vat += lineVat;
  }

  // Возвращаем объект с итогами:
  // net — общая сумма без НДС,
  // vat — общая сумма НДС,
  // gross — общая сумма с НДС (net + vat).
  return { net, vat, gross: net + vat };
}
