data class Bracket(val upTo: BigDecimal?, val rate: BigDecimal)

fun progressiveTax(income: BigDecimal, brackets: List<Bracket>): BigDecimal {
    // Проверяем, что доход неотрицательный, иначе выбрасываем исключение
    require(income >= BigDecimal.ZERO) { "income must be non-negative" }

    // Инициализируем переменную для накопления итоговой суммы налога
    var tax = BigDecimal.ZERO

    // Инициализируем нижнюю границу текущего налогового диапазона (начинаем с нуля)
    var lower = BigDecimal.ZERO

    // Итерируемся по каждому налоговому диапазону (бренкету)
    for (b in brackets) {
        // Если доход меньше или равен текущей нижней границе, значит,
        // мы уже обработали все применимые диапазоны — выходим из цикла
        if (income <= lower) break

        // Определяем верхнюю границу текущего диапазона:
        // - Если у бренда есть верхняя граница (upTo != null), берём минимум между ней и доходом
        //   (чтобы не считать налог с суммы, превышающей доход)
        // - Если upTo == null (последний, "бесконечный" диапазон), то верхней границей является сам доход
        val upper = b.upTo?.min(income) ?: income

        // Вычисляем налог для части дохода, попадающей в текущий диапазон:
        // (верхняя граница - нижняя граница) * ставка налога этого диапазона
        tax += (upper - lower) * b.rate

        // Обновляем нижнюю границу для следующего диапазона:
        // - Если у текущего бренда есть верхняя граница (upTo != null), она становится новой нижней границей
        // - Если upTo == null, значит, это последний диапазон, и дальше обрабатывать нечего — выходим из цикла
        lower = b.upTo ?: break
    }

    // Возвращаем итоговую сумму налога, округлённую до целого числа
    // с использованием стандартного математического округления (половина вверх)
    return tax.setScale(0, RoundingMode.HALF_UP)
}
